using UnityEngine;

public class LifecycleLogger : MonoBehaviour
{
    private int frameCount = 0;
    private int fixedCount = 0;
    private int lateCount = 0;

    void Awake() => Debug.Log("Awake");
    void OnEnable() => Debug.Log("OnEnable");
    void Start() => Debug.Log("Start");

    void Update()
    {
        if (frameCount < 3)
        {
            Debug.Log($"Update frame {frameCount}");
            frameCount++;
        }
    }

    void FixedUpdate()
    {
        if (fixedCount < 3)
        {
            Debug.Log($"FixedUpdate step {fixedCount}");
            fixedCount++;
        }
    }

    void LateUpdate()
    {
        if (lateCount < 3)
        {
            Debug.Log($"LateUpdate step {lateCount}");
            lateCount++;
        }
    }

    void OnDisable() => Debug.Log("OnDisable");
    void OnDestroy() => Debug.Log("OnDestroy");
}
